function escAdmin(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));}document.addEventListener('DOMContentLoaded',async()=>{const el=document.getElementById('devolucoes-real');try{const rows=await apiFetch('/operacoes/admin/devolucoes');el.innerHTML=rows.length?rows.map(d=>`<tr><td>${escAdmin(d.numero)}</td><td>${escAdmin(d.cliente_nome||d.cliente_email||'—')}</td><td>${escAdmin(d.motivo)}</td><td>${escAdmin(d.estado)}</td><td><select onchange="mudarDev(${d.id},this.value)"><option>${escAdmin(d.estado)}</option><option>em_analise</option><option>aprovada</option><option>rejeitada</option><option>recebida</option><option>reembolsada</option><option>cancelada</option></select></td></tr>`).join(''):'<tr><td colspan="5">Ainda não existem solicitações.</td></tr>'}catch(e){el.innerHTML=`<tr><td colspan="5">${escAdmin(e.message)}</td></tr>`}});async function mudarDev(id,estado){try{await apiFetch('/operacoes/admin/devolucoes/'+id,{method:'PUT',body:JSON.stringify({estado})})}catch(e){alert(e.message)}}
